// @ai-proposed SHOP-142 — generated by the verify-feature skill.
// Verifies: AC-2, AC-3 (see verification/SHOP-142/VERIFICATION_PLAN.md)
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from '../../server/server.js';
import { applyDiscount } from '../../server/discounts.js';

let server, base;
before(async () => {
  server = createServer().listen(0, '127.0.0.1');
  await new Promise((r) => server.once('listening', r));
  base = `http://127.0.0.1:${server.address().port}`;
});
after(() => server.close());

const postCode = (code) =>
  fetch(`${base}/api/cart/discount`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ code }),
  });

test('SHOP-142 AC-2 SAVE10 takes 10% off the $120 cart, total 108', async () => {
  const res = await postCode('SAVE10');
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.subtotal, 120);
  assert.equal(body.code, 'SAVE10');
  assert.equal(body.discount, 12);
  assert.equal(body.total, 108);
});

test('SHOP-142 AC-2 FLAT20 takes $20 off the $120 cart, total 100', async () => {
  const res = await postCode('FLAT20');
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.code, 'FLAT20');
  assert.equal(body.discount, 20);
  assert.equal(body.total, 100);
});

test('SHOP-142 AC-2 FLAT20 is refused below a $50 subtotal and applies at exactly $50', () => {
  assert.deepEqual(applyDiscount('FLAT20', 49.99), {
    ok: false,
    error: 'This code needs a subtotal of at least $50.',
  });
  const at50 = applyDiscount('FLAT20', 50);
  assert.equal(at50.ok, true);
  assert.equal(at50.discount, 20);
  assert.equal(at50.total, 30);
});

test('SHOP-142 AC-3 an empty code is rejected with "Enter a discount code."', async () => {
  const res = await postCode('');
  assert.equal(res.status, 400);
  assert.deepEqual(await res.json(), { error: 'Enter a discount code.' });
});

test('SHOP-142 AC-3 an unknown code is rejected with "That code is not valid."', async () => {
  const res = await postCode('NOPE99');
  assert.equal(res.status, 400);
  assert.deepEqual(await res.json(), { error: 'That code is not valid.' });
});
